/// Per-skill availability (issue #1151): the app twin of the CLI `skills:`
/// per-skill toggles over the package builtins.
extension AgentServiceSkills on AgentService {
  /// Whether the skill [name] is enabled — the per-skill toggles
  /// ([SkillsTogglesStore]) default every unmentioned skill ON.
  bool isSkillEnabled(String name) => _skillToggles[name] ?? true;

  /// Switches one skill's availability (the settings "Built-in skills"
  /// rows): persists the choice when a store is wired (fire-and-forget),
  /// then re-discovers skills under the new toggles and recomposes the
  /// system prompt — same shape as [AgentService.setSkillsAccess].
  /// Services built from a pre-constructed [Agent] (tests) have no config:
  /// they record the choice but skip the re-discovery.
  Future<void> setSkillToggle(String name, bool enabled) async {
    if (isSkillEnabled(name) == enabled) return;
    _skillToggles = {..._skillToggles, name: enabled};
    _skillTogglesGeneration++;
    _notify();
    final store = _skillTogglesStore;
    if (store != null) unawaited(store.save(_skillToggles));
    final config = _config;
    if (config == null) return;
    final generation = _skillTogglesGeneration;
    final (suffix, pinSkills) = await _discoverPromptSuffix(
      env,
      _skillsAccess,
      homeDir: _skillsHomeDir ?? desktopHomeDir(),
      skillToggles: _skillToggles,
    );
    // A newer toggle change made while discovery ran wins — don't clobber.
    if (generation != _skillTogglesGeneration) return;
    _promptSuffix = suffix;
    // gh-1409: republish the operative-pin source set (derived state, P2).
    _agent.operativeSkills = pinSkills;
    _agent.state.systemPrompt = _composeSystemPrompt(config);
  }
}

Future<String> generateSummary(
  List<Message> messages, {
  required SummarizeFn summarize,
  String? customInstructions,
  String? previousSummary,
  CancelToken? cancelToken,
  CompactionPrompts prompts = defaultCompactionPrompts,
  String? userRequestCandidates,
  int? maxPromptTokens,
  PinnedOperativePayload? pinnedOperative,
}) async {
  // Issue #1131: the previous checkpoint re-enters this prompt verbatim —
  // heal it first so a poisoned old summary cannot be paraphrased forward
  // into a fresh one (idempotent; clean records are unaffected). gh-1409:
  // pinned lines ride the heal protected (AC4) — a pin inside an old
  // checkpoint survives sanitization byte-identical.
  previousSummary = previousSummary == null
      ? null
      : sanitizeSummary(
          previousSummary,
          protectedLines: pinnedOperative?.lines ?? const {},
        ).text;
  var basePrompt = previousSummary != null
      ? prompts.summaryUpdate
      : prompts.summary;
  // gh-1409 AC3: the verbatim-preserve duty rides the instruction tail of
  // every call whose input carries the pinned block.
  if (pinnedOperative != null) {
    basePrompt = '$basePrompt\n\n${prompts.pinnedOperative}';
  }
  if (customInstructions != null) {
    basePrompt = '$basePrompt\n\nAdditional focus: $customInstructions';
  }
  String build(
    String conversation,
    String? candidates,
    String? prior,
    String instructions,
  ) {
    final prompt = StringBuffer()
      ..write('<conversation>\n')
      ..write(conversation)
      ..write('\n</conversation>\n\n');
    if (candidates != null) {
      prompt
        ..write(candidates)
        ..write('\n\n');
    }
    if (pinnedOperative != null) {
      prompt
        ..write(pinnedOperative.block)
        ..write('\n\n');
    }
    if (prior != null) {
      prompt.write('<previous-checkpoint>\n$prior\n</previous-checkpoint>\n\n');
    }
    prompt.write(instructions);
    return prompt.toString();
  }

  final full = build(
    serializeConversation(messages),
    userRequestCandidates ?? userRequestCandidatesBlock(messages),
    previousSummary,
    basePrompt,
  );
  if (maxPromptTokens == null ||
      estimateStringTokens(full) <= maxPromptTokens) {
    return _runSummarization(
      prompt: full,
      summarize: summarize,
      cancelToken: cancelToken,
      failureLabel: 'Summarization failed',
    );
  }

  // Over the payload budget (#729): chunk the region, fold chunk-wise.
  // Each chunk carries only its own request candidates (the whole-range
  // block would ride every chunk and re-inflate the payload); the record
  // `<id>` pointers degrade to date-only on this path.
  var prior = previousSummary;
  var fold = '';
  final chunks = chunkSummarizableMessages(
    messages,
    max(maxPromptTokens - _chunkEnvelopeReserveTokens, 256),
  );
  for (var i = 0; i < chunks.length; i++) {
    final candidates = userRequestCandidatesBlock(chunks[i]);
    final instructions = i == 0
        ? basePrompt
        : (pinnedOperative == null
