    List<Skill> skills, {
    Set<String> readSkillPaths = const {},
    int? budgetChars,
  }) {
    final byKey = <String, OperativePin>{};
    final order = <String>[];
    for (final skill in skills) {
      for (final line in skill.manifest.operative) {
