    test('without protection the same line WOULD be stripped '
        '(negative guard for the exemption)', () {
      final result = sanitizeSummary('"$pinLine"\n');
      expect(result.text, isNot(contains(pinLine)));
      expect(result.stripped, isNotEmpty);
    });
  });
}

